    public async Task<string?> KeepPromise(int player,bool force=false)
    {
        var prepare=await host.WithState(_=>{var p=Promise(player);if(p==null||S(p,"status")!="open")return(Promise:(JsonObject?)null,Generation:generation,How:(string?)null);if(Day>N(p,"due")){p["status"]="lapsed";C.SetPlayerState(player,"fortune_promise",p);return(Promise:(JsonObject?)null,Generation:generation,How:(string?)null);}if(Hour<8||Hour>=20||!force&&!(Day==N(p,"due")&&Hour>=14)&&!((Day>N(p,"day")||Minute-(N(p,"day")-1)*1440>840)&&C.Roll()<.3))return(Promise:(JsonObject?)null,Generation:generation,How:(string?)null);p["status"]="keeping";C.SetPlayerState(player,"fortune_promise",p);string? how=null;var jef=actions.PlayerPosition(player);string kind=S(p,"kind");if(kind is "meeting"or"gift"){var pool=People.Where(r=>N(r,"age")>=18&&r["visitor"]==null&&S(r,"trade")!="police"&&actions.Of(S(r,"id"))==null&&actions.Reserved?.Invoke(S(r,"id"))!=true&&N(r["stats"],"warmth")>=(kind=="gift"?5:6)&&(kind!="gift"||S(r,"trade")is "baker"or"grocer"or"fishwife"or"market_woman")).Where(r=>actions.Position(S(r,"id"))is {} at&&!B(at,"indoors")&&jef!=null&&NativeGoods.Distance(N(at,"x"),N(at,"z"),N(jef,"x"),N(jef,"z"))<200).ToArray();if(pool.Length>0){var person=pool[Math.Clamp((int)(C.Roll()*pool.Length),0,pool.Length-1)];families.StartSeek(player,S(person,"id"),kind=="gift"?"gift":"meet",reason:"the cards said so");how=S(person,"name")+" went to find Jef";}}
            else if(kind=="loss"){int lost=Math.Min(5,C.Scalar<int>("SELECT money_c FROM player WHERE id=$p0",player));if(lost>0){C.Execute("UPDATE player SET money_c=money_c-$p0 WHERE id=$p1",lost,player);C.Log(player,"lost",null,"A coin slipped through a hole in Jef's coat pocket: "+lost+" centimes.");host.Publish("families",new(){["say"]="Your pocket feels lighter. A coin has slipped through a hole in the lining: "+lost+" centimes gone.",["jobs"]=true});how="lost "+lost+" centimes";}else how="lost nothing he had";}else{var here=People.FirstOrDefault(r=>S(r["visitor"],"role")=="stranger"&&B(r["visitor"],"here"));if(here!=null){how=S(here,"name")+" is in town";if(jef!=null&&actions.Of(S(here,"id"))==null)families.StartSeek(player,S(here,"id"),"meet",reason:"the cards said so");}}return(Promise:(JsonObject?)p.DeepClone().AsObject(),Generation:generation,How:how);}).ConfigureAwait(false);
        if(prepare.Promise==null)return null;string? how=prepare.How;if(how==null&&S(prepare.Promise,"kind")=="stranger"){var stranger=await Arrive().ConfigureAwait(false);if(stranger!=null)how=S(stranger,"name")+" arrived";}
        return await host.WithState(_=>{if(generation!=prepare.Generation)return null;var p=Promise(player);if(p==null||N(p,"day")!=N(prepare.Promise,"day")||S(p,"status")!="keeping")return null;if(how==null){p["status"]="open";C.SetPlayerState(player,"fortune_promise",p);return null;}if(S(p,"kind")=="stranger"){var here=People.FirstOrDefault(r=>S(r["visitor"],"role")=="stranger"&&B(r["visitor"],"here"));if(here!=null&&actions.PlayerPosition(player)!=null&&actions.Of(S(here,"id"))==null)families.StartSeek(player,S(here,"id"),"meet",reason:"the cards said so");}p["status"]="kept";p["how"]=how;C.SetPlayerState(player,"fortune_promise",p);Fact("director","promise_kept","The cards' promise came true: "+how+".",3);return how;}).ConfigureAwait(false);
    }
    public string EngineDream(int player,int day)
    {
        var verbs=C.Rows("SELECT verb FROM log WHERE day=$p0 AND player_id=$p1 ORDER BY id",day,player).Select(r=>S(r,"verb")).ToHashSet();var bits=new System.Collections.Generic.List<string>();if(verbs.Contains("robbed")||verbs.Contains("assaulted"))bits.Add("A hand reaches into your coat, and when you turn there is only fog, and the fog is laughing.");if(verbs.Contains("finished_job"))bits.Add("You carry sacks up a gangway that never ends; each one is lighter than the last, and at the top your mother counts them.");if(verbs.Contains("stole"))bits.Add("A fishwife follows you through the streets with a herring in each hand, saying nothing at all.");if(verbs.Contains("fortune"))bits.Add("The cards fall from the old woman's hands and turn into gulls.");if(verbs.Contains("supper"))bits.Add("You sit at a long table in a warm kitchen; somebody keeps filling your bowl.");if(bits.Count==0)bits.Add("You walk the quays in the fog, looking for the Kempen road home, and every lamp you pass goes out behind you.");bits.Add("Somewhere a ship's bell rings, and you wake before you can count the strokes.");return string.Join(" ",bits.TakeLast(3));
    }
    public async Task<JsonObject> Dream(int player)
    {
        var prepared=await host.WithState(_=>{int day=Math.Max(1,(int)N(host.Clock.View(),"hour")<=6?Day-1:Day);var old=C.PlayerState(player,"dream")as JsonObject??(player==1?C.World("dream")as JsonObject:null);if(old!=null&&N(old,"day")==day)return(Answer:(JsonObject?)new(){["text"]=S(old,"text"),["source"]=S(old,"source")},Day:day,Text:"",Request:(JsonObject?)null,Generation:generation);string text=EngineDream(player,day);JsonObject? request=null;if(MayCall("dream")){pendingCalls++;request=NativeNorthNarration.Request("dream",new(){["day"]=day,["facts"]=C.Rows("SELECT text FROM log WHERE day=$p0 AND player_id=$p1 ORDER BY id DESC LIMIT 12",day,player)},NativeNorthNarration.Parse("""{"type":"object","properties":{"dream":{"type":"string","minLength":20,"maxLength":420}},"required":["dream"]}"""),"Write 3 to 5 short sentences in second person, made only of this day's things. Strange and a little sad, the fog, river, coins and home. Never a number, weapons, death or harm.");}return(Answer:(JsonObject?)null,Day:day,Text:text,Request:request,Generation:generation);}).ConfigureAwait(false);if(prepared.Answer!=null)return prepared.Answer;JsonObject? output=null;if(prepared.Request!=null)try{output=await NarrateAsync!(player,"dream",prepared.Request).ConfigureAwait(false);}catch{}
        return await host.WithState(_=>{if(generation!=prepared.Generation)throw new NativeServiceException("the week changed while sleeping",409);if(prepared.Request!=null)pendingCalls=Math.Max(0,pendingCalls-1);string text=prepared.Text,source="engine";if(output!=null&&Clean(S(output,"dream"),420)is {} dream&&dream.Length>=20&&!Regex.IsMatch(dream,@"\d")){text=dream;source="claude";}C.SetPlayerState(player,"dream",new JsonObject{["day"]=prepared.Day,["text"]=text,["source"]=source});Fact("log","dream","Jef dreamt ("+source+"): "+text[..Math.Min(200,text.Length)],1);host.Publish("families",new(){["dream"]=text});return new JsonObject{["text"]=text,["source"]=source};}).ConfigureAwait(false);
    }
    private async Task DreamSafely(int player){try{await Dream(player).ConfigureAwait(false);}catch(NativeServiceException error)when(error.Status==409){}catch(Exception error){Console.Error.WriteLine("[native dream] "+error.Message);}}
    private void QueueDream(int player){if(dreams.TryGetValue(player,out var pending)&&!pending.IsCompleted)return;dreams[player]=DreamSafely(player);}
    public async Task<int> TwistRumours(bool force=false)
    {
        var prepared=await host.WithState(_=>{var rows=C.Rows("SELECT id,gist,COALESCE(told_as,gist) AS told FROM npc_memory WHERE source='heard' AND day=$p0 AND gist IS NOT NULL AND gist<>'' AND weight>=3 ORDER BY weight DESC,id DESC LIMIT 6",Day);if(!force&&(N(C.World("twist"),"day")==Day||Hour<12)||rows.Count<2||!MayCall("rumour_twist"))return(Rows:(JsonArray?)null,Request:(JsonObject?)null,Generation:generation);C.SetWorld("twist",new JsonObject{["day"]=Day});pendingCalls++;var request=NativeNorthNarration.Request("rumour_twist",new(){["rumours"]=rows.DeepClone()},NativeNorthNarration.Parse("""{"type":"object","properties":{"tellings":{"type":"array","maxItems":6,"items":{"type":"object","properties":{"id":{"type":"integer"},"told":{"type":"string","maxLength":160}},"required":["id","told"]}}},"required":["tellings"]}"""),"Retell these rumours with a hedge or livelier word. Preserve every fact, person, deed and sum; start with Jef. Nothing worse or new.");return(Rows:(JsonArray?)rows,Request:(JsonObject?)request,Generation:generation);}).ConfigureAwait(false);if(prepared.Request==null)return 0;JsonObject? output=null;try{output=await NarrateAsync!(1,"rumour_twist",prepared.Request).ConfigureAwait(false);}catch{}
        return await host.WithState(_=>{if(generation!=prepared.Generation)return 0;pendingCalls=Math.Max(0,pendingCalls-1);int changed=0;foreach(var telling in A(output?["tellings"]).Take(6)){int id=(int)N(telling,"id");var row=prepared.Rows!.FirstOrDefault(r=>N(r,"id")==id);string text=Regex.Replace(S(telling,"told").Trim(),@"\s+"," ");if(row==null||text.Length>160||!NativeCoreRumours.WithinFact(S(row,"gist"),text))continue;C.Execute("UPDATE npc_memory SET told_as=$p0 WHERE id=$p1 AND gist=$p2",text,id,S(row,"gist"));Fact("rumour","rumour_twist","A rumour drifted in the telling: \""+text+"\" (the fact: "+S(row,"gist")+")",1,new(){["fact"]=S(row,"gist"),["told"]=text});changed++;}return changed;}).ConfigureAwait(false);
    }
    private void Tick(){if(ticking!=null&&!ticking.IsCompleted)return;int token=generation;ticking=TickAsync(token);}
    public async Task Idle(){if(ticking!=null)await ticking.ConfigureAwait(false);foreach(var dream in dreams.Values.ToArray())await dream.ConfigureAwait(false);}
    private async Task TickAsync(int token)
    {
        try{bool heavy=await host.WithState(_=>{if(generation!=token)return false;if(Hour>=7)PlanSchemes();SchemeTick();bool same=N(C.World("surprises"),"hour",-1)==(int)Hour&&N(C.World("surprises"),"day")==Day;if(same)return false;C.SetWorld("surprises",new JsonObject{["hour"]=(int)Hour,["day"]=Day});foreach(var visitor in People.Where(p=>S(p["visitor"],"role")=="stranger"&&B(p["visitor"],"here")).ToArray())if(Day>N(visitor["visitor"],"leaves",99)||Day==N(visitor["visitor"],"leaves",99)&&Hour>=16)LeaveStranger(S(visitor,"id"));return true;}).ConfigureAwait(false);if(!heavy)return;bool arrive=await host.WithState(_=>generation==token&&Hour>=8&&Hour<17&&!People.Any(p=>S(p["visitor"],"role")=="stranger"&&B(p["visitor"],"here"))&&Day>=N(C.World("strangers"),"next")&&C.Roll()<.2).ConfigureAwait(false);if(arrive)await Arrive().ConfigureAwait(false);foreach(int player in host.OnlinePlayers())await KeepPromise(player).ConfigureAwait(false);await TwistRumours().ConfigureAwait(false);}catch(Exception error){Console.Error.WriteLine("[native surprises] "+error.Message);}
    }
    private async Task<object?> DevAsync(NativeServiceRequest request)
    {
        switch(request.Text("do")){case "fortune":return await TellFortune(request.PlayerId).ConfigureAwait(false);case "stranger":var stranger=await Arrive(Kinds.Contains(request.Text("kind"))?request.Text("kind"):null).ConfigureAwait(false);return new JsonObject{["ok"]=stranger!=null,["stranger"]=stranger==null?null:new JsonObject{["id"]=S(stranger,"id"),["name"]=S(stranger,"name"),["story"]=S(stranger["visitor"],"story"),["goal"]=S(stranger["visitor"],"goal")}};case "promise":var kept=await KeepPromise(request.PlayerId,true).ConfigureAwait(false);return await host.WithState(_=>new JsonObject{["promise"]=Promise(request.PlayerId)?.DeepClone(),["kept"]=kept}).ConfigureAwait(false);case "dream":return await Dream(request.PlayerId).ConfigureAwait(false);case "twist":return new JsonObject{["twisted"]=await TwistRumours(true).ConfigureAwait(false)};case "schemes":return await host.WithState(_=>new JsonObject{["schemes"]=PlanSchemes()}).ConfigureAwait(false);default:return new JsonObject{["ok"]=false,["why"]="do: fortune, stranger, promise, schemes, twist, dream"};}
    }
